import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, interpolateColors } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }

// Helper function from reference to darken colors
const darkenColor = (hex: string, percent: number): string => {
  let color = hex.startsWith('#') ? hex.slice(1) : hex;
  if (color.length === 3) {
    color = color
      .split('')
      .map(c => c + c)
      .join('');
  }
  const num = parseInt(color, 16);
  let r = (num >> 16) & 0xff;
  let g = (num >> 8) & 0xff;
  let b = num & 0xff;
  r = Math.max(0, Math.min(255, Math.floor(r * (1 - percent))));
  g = Math.max(0, Math.min(255, Math.floor(g * (1 - percent))));
  b = Math.max(0, Math.min(255, Math.floor(b * (1 - percent))));
  return '#' + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1).toUpperCase();
};



export type FolderAnimationProps = Record<string, any>;

const FolderAnimation: React.FC<FolderAnimationProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = true,
  durationInSeconds = 5,
  folderColor = "#70a1ff",
  scale = 2.5,
}) => {
  useFontLoader(["Inter"]);
  
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color Calculations
  const folderBackColor = darkenColor(folderColor, 0.08);
  const paper1Color = darkenColor('#ffffff', 0.1);
  const paper2Color = darkenColor('#ffffff', 0.05);
  const paper3Color = '#ffffff';
  
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Animation Drivers
  // Open animation starts at 1 second
  const openStartFrame = fps * 1; 
  const openDriver = spring({
    frame: frame - openStartFrame,
    fps,
    config: { damping: 12, stiffness: 100 }
  });

  // Folder Front Animations
  const frontSkew = interpolate(openDriver, [0, 1], [0, 15]);
  const frontScaleY = interpolate(openDriver, [0, 1], [1, 0.6]);
  
  const rightSkew = interpolate(openDriver, [0, 1], [0, -15]);
  const rightScaleY = interpolate(openDriver, [0, 1], [1, 0.6]);

  // Paper Animations
  // Paper 1: translate(-120%, -70%) rotateZ(-15deg)
  const p1X = interpolate(openDriver, [0, 1], [-50, -120]);
  const p1Y = interpolate(openDriver, [0, 1], [10, -70]);
  const p1Rot = interpolate(openDriver, [0, 1], [0, -15]);

  // Paper 2: translate(10%, -70%) rotateZ(15deg)
  const p2X = interpolate(openDriver, [0, 1], [-50, 10]);
  const p2Y = interpolate(openDriver, [0, 1], [10, -70]);
  const p2Rot = interpolate(openDriver, [0, 1], [0, 15]);

  // Paper 3: translate(-50%, -100%) rotateZ(5deg)
  const p3X = interpolate(openDriver, [0, 1], [-50, -50]);
  const p3Y = interpolate(openDriver, [0, 1], [10, -100]);
  const p3Rot = interpolate(openDriver, [0, 1], [0, 5]);

  // Hover/Bobbing Effect (Continuous)
  const hoverOffset = Math.sin(frame / 20) * 5; 

  const baseStyle: React.CSSProperties = {
    position: 'absolute',
    width: '100px',
    height: '80px',
    backgroundColor: folderBackColor,
    borderRadius: '0px 10px 10px 10px',
    transform: `translate(-50%, -50%) scale(${scale}) translateY(${hoverOffset}px)`,
    left: '50%',
    top: '50%',
  };

  const tabStyle: React.CSSProperties = {
    position: 'absolute',
    bottom: '98%',
    left: 0,
    width: '30px',
    height: '10px',
    backgroundColor: folderBackColor,
    borderRadius: '5px 5px 0 0',
  };

  const paperBaseStyle: React.CSSProperties = {
    position: 'absolute',
    bottom: '10%',
    left: '50%',
    borderRadius: '0px', // Changed from 10px to 0px to make papers rectangular
    transition: 'none', // Critical for Remotion
    zIndex: 2,
  };

  const frontBaseStyle: React.CSSProperties = {
    position: 'absolute',
    width: '100%',
    height: '100%',
    backgroundColor: folderColor,
    borderRadius: '5px 10px 10px 10px',
    transformOrigin: 'bottom',
    zIndex: 3,
    transition: 'none',
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {/* Main Folder Container */}
      <div style={baseStyle}>
        
        {/* Folder Tab */}
        <div style={tabStyle} />

        {/* Paper 1 */}
        <div
          style={{
            ...paperBaseStyle,
            width: '70%',
            height: '60%',
            backgroundColor: paper1Color,
            transform: `translate(${p1X}%, ${p1Y}%) rotateZ(${p1Rot}deg)`,
          }}
        />

        {/* Paper 2 */}
        <div
          style={{
            ...paperBaseStyle,
            width: '80%',
            height: '70%',
            backgroundColor: paper2Color,
            zIndex: 2, // Layering logic from CSS
            transform: `translate(${p2X}%, ${p2Y}%) rotateZ(${p2Rot}deg)`,
          }}
        />

        {/* Paper 3 (Topmost Paper) */}
        <div
          style={{
            ...paperBaseStyle,
            width: '90%',
            height: '60%',
            backgroundColor: paper3Color,
            zIndex: 2,
            transform: `translate(${p3X}%, ${p3Y}%) rotateZ(${p3Rot}deg)`,
          }}
        />

        {/* Folder Front (Right/Shadow Layer) */}
        <div
          style={{
            ...frontBaseStyle,
            transform: `skew(${rightSkew}deg) scaleY(${rightScaleY})`,
            opacity: 0.8, // Slight transparency to distinguish layers if they overlap
          }}
        />

        {/* Folder Front (Main Layer) */}
        <div
          style={{
            ...frontBaseStyle,
            transform: `skew(${frontSkew}deg) scaleY(${frontScaleY})`,
          }}
        />

      </div>
    </AbsoluteFill>
  );
};

export default FolderAnimation;